import { readFileSync } from "fs";

const [a, b] = readFileSync(0, "utf8").trim().split(" ").map(BigInt);

// ユークリッドの互除法
function gcd(x: bigint, y: bigint): bigint {
  while (y !== 0n) {
    [x, y] = [y, x % y];
  }
  return x;
}
const g = gcd(a, b);
// 最小公倍数は最大 10¹⁸ 程度になるので BigInt で計算する
console.log(g + " " + (a / g) * b);
